// 桩（对齐真 SDK `@deepseek-ai/dsh-llm/lib/types/error.js` 的 HarnessError 形状）：
// 真 SDK 的 `@deepseek-ai/dsh-tools` 不 re-export HarnessError，插件需从 `@deepseek-ai/dsh-llm` 取。
// 此桩让离线测试能 import 到带 `code` 的 HarnessError（而非降级为裸 Error、丢 code）。
export class HarnessError extends Error {
  constructor(message, code) {
    super(message)
    this.code = code
    this.name = 'HarnessError'
  }
}

// ── 消息构造（E1 break-glass 的会话提醒要用 `agent.send`，它收 `UserMessage`）──
// ⚠️ 形状对齐真 SDK `@deepseek-ai/dsh-llm/lib/types/message.js`：`createMessage` = 补 id 后
//    `structuredClone` + **深冻结**。这里逐条照做 —— 桩与真实现的差别如果只是"少冻一层"，
//    那些差别**永远不会在离线测试里暴露**，却会在活体里变成"消息被下游改坏"。

import { randomUUID } from 'node:crypto'

/** 递归冻结（对齐真实现的 deepFreeze）。 */
function deepFreeze(value) {
  if (value !== null && typeof value === 'object' && !Object.isFrozen(value)) {
    Object.freeze(value)
    for (const k of Object.keys(value)) deepFreeze(value[k])
  }
  return value
}

/** 冻结一份已带 id 的消息（真实现：`deepFreeze(structuredClone(m))`）。 */
export function freezeMessage(message) {
  return deepFreeze(structuredClone(message))
}

/** 造一条带新 id 的消息（`input` 不得自带 id/role）。 */
export function createMessage(input) {
  return freezeMessage({ ...input, id: randomUUID() })
}

/** 造一条 user 角色的消息。 */
export function createUserMessage(input) {
  return createMessage({ ...input, role: 'user' })
}
